type DenialReason = "THROUGHPUT_SLA" | string;

interface AllowListedEndpoint {
  endpointId: string;
  hardDenials?: DenialReason[];
}

/**
 * Returns true when the sole allow-listed endpoint is hard-denied only by
 * throughput SLA, allowing a fallback selection instead of returning an error.
 */
function allowSoleThroughputSlaFallback(
  allowListedCandidates: AllowListedEndpoint[]
): boolean {
  if (allowListedCandidates.length !== 1) {
    return false;
  }

  const [soleCandidate] = allowListedCandidates;
  const denials = soleCandidate.hardDenials ?? [];

  if (denials.length === 0) {
    return false;
  }

  return denials.every((reason) => reason === "THROUGHPUT_SLA");
}
